--
-- Table structure for table `envio`
--

DROP TABLE IF EXISTS `envio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `envio` (
  `nro_envio` int(11) NOT NULL AUTO_INCREMENT,
  `fecha_envio` date NOT NULL,
  `peso_kg` decimal(8,2) NOT NULL,
  `tipo_cont_cod` char(3) NOT NULL,
  `remitente_dni` int(11) NOT NULL,
  `destinatario_dni` int(11) NOT NULL,
  `sucursal_orig_cod` varchar(10) NOT NULL,
  `sucursal_dest_cod` varchar(10) NOT NULL,
  `direccion_entrega_id` int(11) NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`nro_envio`),
  KEY `fk_envio_tipo_cont` (`tipo_cont_cod`),
  KEY `fk_envio_suc_orig` (`sucursal_orig_cod`),
  KEY `fk_envio_suc_dest` (`sucursal_dest_cod`),
  KEY `fk_envio_direccion` (`direccion_entrega_id`),
  KEY `idx_envio_remitente` (`remitente_dni`),
  KEY `idx_envio_destinatario` (`destinatario_dni`),
  KEY `idx_envio_fecha` (`fecha_envio`),
  CONSTRAINT `fk_envio_destinatario` FOREIGN KEY (`destinatario_dni`) REFERENCES `cliente` (`cliente_dni`),
  CONSTRAINT `fk_envio_direccion` FOREIGN KEY (`direccion_entrega_id`) REFERENCES `direccion` (`direccion_id`),
  CONSTRAINT `fk_envio_remitente` FOREIGN KEY (`remitente_dni`) REFERENCES `cliente` (`cliente_dni`),
  CONSTRAINT `fk_envio_suc_dest` FOREIGN KEY (`sucursal_dest_cod`) REFERENCES `sucursal` (`sucursal_cod`),
  CONSTRAINT `fk_envio_suc_orig` FOREIGN KEY (`sucursal_orig_cod`) REFERENCES `sucursal` (`sucursal_cod`),
  CONSTRAINT `fk_envio_tipo_cont` FOREIGN KEY (`tipo_cont_cod`) REFERENCES `tipo_contenido` (`tipo_cont_cod`),
  CONSTRAINT `ck_sucursales_distintas` CHECK (`sucursal_orig_cod` <> `sucursal_dest_cod`),
  CONSTRAINT `ck_peso_positivo` CHECK (`peso_kg` > 0)
) ENGINE=InnoDB AUTO_INCREMENT=8938 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

