  CONSTRAINT `fk_hist_sucursal` FOREIGN KEY (`sucursal_cod`) REFERENCES `sucursal` (`sucursal_cod`)
) ENGINE=InnoDB AUTO_INCREMENT=38371 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
