--
-- Table structure for table `viaje`
--

DROP TABLE IF EXISTS `viaje`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `viaje` (
  `viaje_id` int(11) NOT NULL AUTO_INCREMENT,
  `fecha_salida` datetime NOT NULL,
  `llegada_estimada` datetime GENERATED ALWAYS AS (`fecha_salida` + interval 24 hour) VIRTUAL,
  `fecha_llegada` datetime DEFAULT NULL,
  `sucursal_origen_cod` varchar(10) NOT NULL,
  `sucursal_destino_cod` varchar(10) NOT NULL,
  `vehiculo_patente` varchar(10) NOT NULL,
  `chofer_legajo` int(11) NOT NULL,
  PRIMARY KEY (`viaje_id`),
  KEY `fk_viaje_chofer` (`chofer_legajo`),
  KEY `idx_viaje_patente` (`vehiculo_patente`),
  KEY `fk_viaje_sucursal_origen` (`sucursal_origen_cod`),
  KEY `fk_viaje_sucursal_destino` (`sucursal_destino_cod`),
  KEY `idx_viaje_salida` (`fecha_salida`),
  CONSTRAINT `fk_viaje_chofer` FOREIGN KEY (`chofer_legajo`) REFERENCES `chofer` (`chofer_legajo`),
  CONSTRAINT `fk_viaje_sucursal_destino` FOREIGN KEY (`sucursal_destino_cod`) REFERENCES `sucursal` (`sucursal_cod`),
  CONSTRAINT `fk_viaje_sucursal_origen` FOREIGN KEY (`sucursal_origen_cod`) REFERENCES `sucursal` (`sucursal_cod`),
  CONSTRAINT `fk_viaje_vehiculo` FOREIGN KEY (`vehiculo_patente`) REFERENCES `vehiculo` (`vehiculo_patente`),
  CONSTRAINT `ck_viaje_origen_destino` CHECK (`sucursal_origen_cod` <> `sucursal_destino_cod`)
) ENGINE=InnoDB AUTO_INCREMENT=3271 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

