/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trigger_before_delete_viaje
BEFORE DELETE ON viaje
FOR EACH ROW
BEGIN
    DECLARE cantidad_envios_asignados INT;

    SELECT COUNT(*) INTO cantidad_envios_asignados
    FROM viaje_envio
    WHERE viaje_id = OLD.viaje_id;

    IF cantidad_envios_asignados > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No se puede eliminar el viaje porque tiene envíos asignados';
    END IF;
END */;;
DELIMITER ;
