--
-- Table structure for table `viaje_envio`
--

DROP TABLE IF EXISTS `viaje_envio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `viaje_envio` (
  `viaje_id` int(11) NOT NULL,
  `nro_envio` int(11) NOT NULL,
  `tramo` tinyint(4) NOT NULL DEFAULT 1,
  PRIMARY KEY (`viaje_id`,`nro_envio`),
  UNIQUE KEY `uq_viaje_envio_tramo` (`nro_envio`,`tramo`),
  CONSTRAINT `fk_ve_envio` FOREIGN KEY (`nro_envio`) REFERENCES `envio` (`nro_envio`),
  CONSTRAINT `fk_ve_viaje` FOREIGN KEY (`viaje_id`) REFERENCES `viaje` (`viaje_id`),
  CONSTRAINT `ck_viaje_envio_tramo` CHECK (`tramo` >= 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

