    READS SQL DATA
BEGIN
    DECLARE v_carga DECIMAL(10,2);
    SELECT COALESCE(SUM(e.peso_kg), 0) INTO v_carga
      FROM viaje_envio x JOIN envio e ON e.nro_envio = x.nro_envio
     WHERE x.viaje_id = p_viaje_id;
    RETURN v_carga;
