    READS SQL DATA
BEGIN
    DECLARE v_estado VARCHAR(30) DEFAULT NULL;   
    SELECT estado INTO v_estado
      FROM historial_estado
     WHERE nro_envio = p_nro_envio
     ORDER BY fecha_hora DESC, id_historial DESC
     LIMIT 1;
    RETURN v_estado;
