CREATE DEFINER=`root`@`localhost` PROCEDURE `procedimiento_asignar_envio_a_viaje`(
    IN id_del_viaje    INT,
    IN numero_de_envio INT
)
BEGIN
    DECLARE cantidad_asignaciones_existentes INT;

    SELECT COUNT(*) INTO cantidad_asignaciones_existentes
    FROM viaje_envio
    WHERE viaje_id = id_del_viaje
      AND nro_envio = numero_de_envio;

    IF cantidad_asignaciones_existentes > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El envío ya está asignado a este viaje';
    ELSE
        INSERT INTO viaje_envio (viaje_id, nro_envio)
        VALUES (id_del_viaje, numero_de_envio);
        SELECT 'Envío asignado correctamente' AS mensaje;
    END IF;
END ;;
DELIMITER ;
